    howTo: [['Get the employee\'s request', 'Check the form or spec from the requester; confirm whether salary must be included.'], ['Confirm authorisation for salary', 'Only disclose pay with the employee\'s written consent.'], ['Verify the facts', 'Check start date, current title, status and pay against HR records.'], ['Print on letterhead', 'Use company letterhead and include HR contact details for verification calls.'], ['Sign and send', 'Sign it, give the original to the employee, and keep a copy on file.']],
    related: [['Reference letter', 'templates/reference-letter-template.html', 'When the requester wants more than dates and title.'], ['Offer letter', 'templates/offer-letter-template.html', 'Original offer showing start terms.'], ['Promotion letter', 'templates/promotion-letter-template.html', 'Confirms title and pay changes.'], ['Severance agreement', 'templates/severance-agreement-template.html', 'For former employees post-termination.'], ['Free HR letter templates', 'for/hr-teams.html', 'Full HR letter library.']],
    faq: [['Must I include salary?', 'Only if the employee authorises it and the requester needs it (e.g. a mortgage lender). Basic letters often omit pay.'], ['Can I refuse?', 'For current employees it is standard practice; for former employees many companies confirm dates and title only.'], ['Is there a legal form?', 'No - a signed letter on company letterhead is accepted by most requesters.'], ['Can I say negative things?', 'Stick to factual confirmation; negative statements can lead to defamation claims.'], ['How long should it take?', 'Most companies produce them within 2-3 business days.']],
    cta: { label: 'Build your verification letter', href: 'app/#/start/employment-verification-letter' },
    download: { href: 'samples/employment-verification-letter.docx', label: 'Download Word' }
