    path: 'templates/eviction-notice-template.html',
    section: 'templates',
    sectionLabel: 'Templates',
    title: 'Eviction Notice | Free Letter Template',
    description: 'Free eviction notice template: cure-or-quit notice for lease violations leading to eviction proceedings.',
    h1: 'Eviction notice',
    lead: 'A formal notice that eviction proceedings will begin if the tenant does not fix a lease violation (or leave) within the required deadline. Used after pay-or-quit or cure-or-quit deadlines have expired.',
    introParagraphs: ['An eviction notice (cure-or-quit or unconditional quit) tells the tenant they have violated the lease and must either fix the violation (cure) or move out (quit) within a set number of days, or the landlord will file for eviction in court.', 'Eviction is heavily regulated - every step is dictated by state and local law. Using the wrong form, wrong notice period, or wrong delivery method can dismiss your case and force you to start over.'],
    bullets: [['Tenant and property', 'Tenant names, property address and unit number, landlord/manager.'], ['Violation', 'Specific lease violation (non-payment, unauthorised pet, property damage, illegal activity) and dates of prior notices.'], ['Cure or quit', 'Either fix the violation by X date (pay rent, remove pet, etc.) or vacate the property by Y date.'], ['Unconditional quit', 'For severe violations (illegal activity, repeated non-payment, substantial damage), the notice may require leaving without option to cure.'], ['Court filing warning', 'Notice that failure to comply will result in an unlawful detainer/eviction lawsuit and possible money judgment.']],
    howTo: [['Get legal guidance', 'Consult a landlord-tenant attorney or local housing authority on the correct notice type and period.'], ['Use the correct form', 'Cure-or-quit for curable violations; unconditional quit for severe breaches; pay-or-stay/quit for rent only.'], ['Reference prior notices', 'Cite dates and types of any earlier notices already served on the tenant.'], ['Deliver per statute', 'Follow exact service rules - hand it to the tenant, post on the door AND mail certified, as required.'], ['File with the court if needed', 'If the tenant does not comply by the deadline, file for eviction in the appropriate court with proof of service.']],
    related: [['Late rent notice', 'templates/late-rent-notice-template.html', 'Pay-or-quit notice before eviction stage.'], ['Notice to vacate', 'templates/notice-to-vacate-template.html', 'End-of-tenancy notice for non-renewal.'], ['Lease termination agreement', 'templates/lease-termination-agreement.html', 'Mutual early move-out instead of eviction.'], ['Payment demand letter', 'templates/payment-demand-letter.html', 'Formal demand for unpaid rent before court.'], ['Free landlord forms', 'for/landlords.html', 'Full landlord/tenant template set.']],
    faq: [['Can I evict without notice?', 'Almost never. Even illegal activity usually requires some notice. Self-help eviction (lockouts, shutting off utilities) is illegal everywhere.'], ['How long is the notice?', '3-30 days depending on state, reason and lease type. Illegal activity can sometimes be 24 hours; non-payment typically 3-14 days.'], ['Do I need a lawyer?', 'Small claims/landlord-tenant court may allow self-representation but an attorney is recommended for anything complex.'], ['What if they pay during the notice?', 'In most states full payment of rent within the pay-or-quit period stops the eviction for that non-payment episode.'], ['How long does eviction take?', 'Anywhere from 2 weeks to 3+ months depending on the state, court backlog and tenant defences.']],
    cta: { label: 'Read the landlord guide first', href: 'guides/how-to-write-a-notice-to-vacate.html' },
