    howTo: [['Check local notice rules', 'Most areas require renewal/non-renewal notices 30-90 days before lease end; some rent-controlled areas require more.'], ['Decide terms early', 'Confirm rent, term length and any policy changes before drafting.'], ['Send the letter', 'Mail or email per the lease notice clause; keep a signed/dated copy and proof of delivery.'], ['Get a signed response', 'Ask the tenant to sign and return by the deadline, or sign a new lease.'], ['Handle non-response', 'If the tenant does not respond, follow local law — typically the lease goes month-to-month or the tenant must vacate.']],
